const fields = Array.isArray(input.fields) ? input.fields : [input.fields];

const field = fields.find(f => 
  f !== null && 
  f !== undefined && 
  String(f.id) === String(input.field_id)
);

const ra = field && field.values && field.values[0] 
  ? field.values[0].value 
  : null;

return { ra: ra };
